import { deepClone, hashValue } from './hand-runtime.mjs';
import { TRANSIENT_IMPULSE_HANDS } from './transient-impulse-hands.mjs';

const clamp = (value, min, max) => Math.max(min, Math.min(max, Number(value)));
const round6 = (value) => Number(Number(value).toFixed(6));

function hand(id, execute, description) {
  return Object.freeze({
    schema: 'axm.hand/v0.1',
    id,
    version: '0.1.0',
    deterministic: true,
    callerNeutral: true,
    network: 'forbidden',
    description,
    execute,
  });
}

function boundedDimension(value, fallback, label) {
  const number = Number(value ?? fallback);
  if (!Number.isFinite(number)) throw new Error(`${label} must be finite`);
  return Math.round(clamp(number, 64, 4096));
}

function colorTriplet(value, fallback) {
  const source = Array.isArray(value) ? value : fallback;
  return source.slice(0, 3).map((channel) => Math.round(clamp(channel, 0, 1) * 255));
}

function canvasProgram(model) {
  return `// Generated by axm.vfx.transient-impulse-canvas2d/v0.1\nconst MODEL = ${JSON.stringify(model)};\n\nfunction clamp01(value) { return Math.max(0, Math.min(1, value)); }\n\nfunction envelopeAt(t) {\n  const samples = MODEL.envelope.samples;\n  if (t <= samples[0].t) return samples[0];\n  if (t >= samples[samples.length - 1].t) return samples[samples.length - 1];\n  for (let index = 1; index < samples.length; index += 1) {\n    const right = samples[index];\n    if (t <= right.t) {\n      const left = samples[index - 1];\n      const span = Math.max(1e-9, right.t - left.t);\n      const mix = (t - left.t) / span;\n      return {\n        intensity: left.intensity + (right.intensity - left.intensity) * mix,\n        expansion: left.expansion + (right.expansion - left.expansion) * mix,\n      };\n    }\n  }\n  return samples[samples.length - 1];\n}\n\nfunction rgb(channels, alpha) {\n  return \`rgba(\${channels[0]}, \${channels[1]}, \${channels[2]}, \${clamp01(alpha)})\`;\n}\n\nexport function render(ctx, elapsedSeconds = 0) {\n  if (!ctx || typeof ctx.save !== 'function') throw new Error('Canvas2D renderer requires a 2D drawing context');\n  const duration = MODEL.envelope.duration;\n  const normalizedTime = clamp01(Number(elapsedSeconds) / Math.max(1e-9, duration));\n  const envelope = envelopeAt(normalizedTime);\n  const expansion = envelope.expansion;\n  const intensity = envelope.intensity;\n\n  ctx.save();\n  ctx.fillStyle = MODEL.style.background;\n  ctx.fillRect(0, 0, MODEL.viewport.width, MODEL.viewport.height);\n  ctx.lineCap = 'round';\n\n  for (const operation of MODEL.operations) {\n    const localTime = clamp01((normalizedTime - operation.phase * operation.phaseWindow) / Math.max(1e-9, 1 - operation.phase * operation.phaseWindow));\n    const localOpacity = clamp01(operation.opacity * intensity * (1 - Math.max(0, localTime - 0.12) / 0.88));\n    if (localOpacity <= 0) continue;\n\n    ctx.save();\n    ctx.strokeStyle = rgb(operation.color, localOpacity);\n    ctx.fillStyle = rgb(operation.color, localOpacity);\n    ctx.lineWidth = operation.width ?? 1;\n\n    if (operation.op === 'ellipse') {\n      ctx.beginPath();\n      ctx.ellipse(operation.center[0], operation.center[1], operation.radii[0] * expansion, operation.radii[1] * expansion, operation.rotation, 0, Math.PI * 2);\n      ctx.stroke();\n    } else if (operation.op === 'segment') {\n      const x1 = operation.start[0];\n      const y1 = operation.start[1];\n      const x2 = x1 + (operation.end[0] - x1) * expansion;\n      const y2 = y1 + (operation.end[1] - y1) * expansion;\n      ctx.beginPath();\n      ctx.moveTo(x1, y1);\n      ctx.lineTo(x2, y2);\n      ctx.stroke();\n    } else if (operation.op === 'core') {\n      ctx.beginPath();\n      ctx.arc(operation.center[0], operation.center[1], Math.max(1, operation.radius * (0.35 + 0.65 * intensity)), 0, Math.PI * 2);\n      ctx.fill();\n    }\n    ctx.restore();\n  }\n\n  ctx.restore();\n  return { normalizedTime, intensity, expansion, operationCount: MODEL.operations.length };\n}\n\nexport function getModel() { return MODEL; }\n`;
}

export const impulseCanvas2dHand = hand('fx.impulse.canvas2d-realize', (state, params = {}) => {
  const next = deepClone(state);
  if (!next.impulseField || !next.impulseEnvelope) {
    throw new Error('canvas2d-realize requires impulse field + envelope');
  }

  const width = boundedDimension(params.width, 1000, 'canvas2d.width');
  const height = boundedDimension(params.height, 600, 'canvas2d.height');
  const event = next.event;
  const field = next.impulseField.geometry;
  const primary = colorTriplet(next.effect?.tint, [0.25, 0.9, 1]);
  const accent = colorTriplet(next.effect?.accent, [1, 0.55, 0.2]);
  const cx = round6(event.origin[0] * width);
  const cy = round6(event.origin[1] * height);
  const radius = round6(event.radius * Math.min(width, height));

  const operations = [];

  for (const ring of field.rings) {
    const rx = round6(radius * ring.radiusScale);
    const ry = round6(rx * ring.axisRatio);
    operations.push({
      op: 'ellipse',
      id: ring.id,
      center: [cx, cy],
      radii: [rx, ry],
      rotation: ring.rotation,
      width: round6(Math.max(0.7, 4.2 * ring.widthScale)),
      opacity: round6(clamp(ring.intensity * 0.55, 0.08, 0.9)),
      color: primary,
      phase: ring.phase,
      phaseWindow: 0.16,
    });
  }

  for (const spoke of field.spokes) {
    const start = radius * spoke.startScale;
    const end = radius * spoke.lengthScale;
    operations.push({
      op: 'segment',
      id: spoke.id,
      start: [
        round6(cx + Math.cos(spoke.angle) * start),
        round6(cy + Math.sin(spoke.angle) * start),
      ],
      end: [
        round6(cx + Math.cos(spoke.angle + spoke.bend) * end),
        round6(cy + Math.sin(spoke.angle + spoke.bend) * end),
      ],
      width: round6(Math.max(0.5, 3.4 * spoke.widthScale)),
      opacity: round6(clamp(spoke.intensity * 0.52, 0.06, 0.92)),
      color: accent,
      phase: spoke.phase,
      phaseWindow: 0.12,
    });
  }

  for (const fragment of field.fragments) {
    const distance = radius * fragment.radialScale;
    const tangent = fragment.angle + Math.PI / 2;
    const x = cx + Math.cos(fragment.angle) * distance + Math.cos(tangent) * radius * fragment.tangentScale;
    const y = cy + Math.sin(fragment.angle) * distance + Math.sin(tangent) * radius * fragment.tangentScale;
    const half = radius * fragment.lengthScale * 0.5;
    operations.push({
      op: 'segment',
      id: fragment.id,
      start: [
        round6(x - Math.cos(fragment.angle) * half),
        round6(y - Math.sin(fragment.angle) * half),
      ],
      end: [
        round6(x + Math.cos(fragment.angle) * half),
        round6(y + Math.sin(fragment.angle) * half),
      ],
      width: 1.4,
      opacity: round6(clamp(fragment.intensity * 0.48, 0.04, 0.8)),
      color: primary,
      phase: fragment.phase,
      phaseWindow: 0.2,
    });
  }

  operations.push({
    op: 'core',
    id: 'core',
    center: [cx, cy],
    radius: round6(Math.max(8, radius * 0.09)),
    width: 0,
    opacity: 0.9,
    color: accent,
    phase: 0,
    phaseWindow: 0,
  });

  const model = {
    schema: 'axm.canvas2d-effect-model/v0.1',
    effect: 'transient-impulse',
    viewport: { width, height },
    canonicalEventHash: next.eventCanonicalHash,
    fieldGeometryHash: next.impulseField.geometryHash,
    envelope: {
      duration: next.impulseEnvelope.duration,
      attack: next.impulseEnvelope.attack,
      samples: deepClone(next.impulseEnvelope.samples),
    },
    style: {
      background: '#03060b',
      primary,
      accent,
    },
    operations,
  };

  const sourceHash = hashValue({
    event: next.event,
    field: next.impulseField,
    envelope: next.impulseEnvelope,
    effect: next.effect,
  });
  const modelHash = hashValue(model);
  const content = canvasProgram(model);

  next.realizations ??= {};
  next.realizations.transientImpulseCanvas2d = {
    mediaType: 'application/javascript',
    renderer: 'axm.vfx.transient-impulse-canvas2d/v0.1',
    derivedFromStateHash: sourceHash,
    canonicalEventHash: next.eventCanonicalHash,
    fieldGeometryHash: next.impulseField.geometryHash,
    oneShotDuration: event.duration,
    modelHash,
    operationCount: operations.length,
    model,
    content,
  };

  return {
    state: next,
    evidence: {
      renderer: 'axm.vfx.transient-impulse-canvas2d/v0.1',
      bytes: Buffer.byteLength(content),
      modelHash,
      operationCount: operations.length,
      canonicalEventHash: next.eventCanonicalHash,
      fieldGeometryHash: next.impulseField.geometryHash,
    },
  };
}, 'Realize the derived impulse field as a disposable Canvas2D program without changing canonical effect state.');

export const TRANSIENT_IMPULSE_CANVAS2D_HANDS = [
  ...TRANSIENT_IMPULSE_HANDS,
  impulseCanvas2dHand,
];

export const TRANSIENT_IMPULSE_CANVAS2D_GRAPH = Object.freeze({
  schema: 'axm.hand-graph/v0.1',
  id: 'fx.transient-impulse.canvas2d',
  version: '0.1.0',
  stages: [
    { id: 'normalize-event', hand: 'fx.impulse.event-normalize', params: {} },
    { id: 'build-field', hand: 'fx.impulse.field-build', params: { maxRings: 8, maxSpokes: 18, maxFragments: 42 } },
    { id: 'temporal-envelope', hand: 'fx.impulse.temporal-envelope', params: { samples: 17, attack: 0.12 } },
    { id: 'realize-canvas2d', hand: 'fx.impulse.canvas2d-realize', params: { width: 1000, height: 600 } },
  ],
});
